#include <Arduino.h>
#include <Adafruit_GFX.h>    // 画面描画用ライブラリ
#include <Adafruit_ST7735.h> // ST7735専用ライブラリ
#include <SPI.h>

// 配線したピンの定義
#define TFT_CS     0  // D0
#define TFT_RST    1  // D1
#define TFT_DC     3  // D3

// ST7735のインスタンス（画面オブジェクト）を作成
Adafruit_ST7735 tft = Adafruit_ST7735(TFT_CS, TFT_DC, TFT_RST);

void setup() {
  // 【最重要】Chromebookの通知連打を防ぐ命綱
  Serial.begin(115200);
  delay(1000); 

  // 128x160のST7735液晶を初期化（黒基板や緑基板など、タブの色に合わせて調整します）
  tft.initR(INITR_BLACKTAB); 

  // 画面を「青色」で塗りつぶして初期化
  tft.fillScreen(ST7735_BLUE);

  // 文字の設定
  tft.setCursor(10, 50);          // 文字を書き始める位置 (X, Y)
  tft.setTextColor(ST7735_WHITE); // 文字の色を白にする
  tft.setTextSize(2);             // 文字のサイズ（1〜3程度）

  // 画面に文字を表示
  tft.println("Hello XIAO!");
}

void loop() {
  // 今回は表示させるだけなのでloop内は空っぽで大丈夫です
}
